<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 25;
const int INF = 10007;
const int MAXT = 65;
const int MAXC = 12;

int n, k;
string A[MAXN], B[MAXN];
int distB[MAXN][MAXN];
int reach[MAXT][MAXC][MAXC][MAXC][MAXC];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};
vector<pair<int,int>> sourceSet, sinkSet;

struct EdmondsKarp {
    int n;
    vector<vector<int>> cap;
    vector<vector<int>> adj;

    EdmondsKarp(int n) : n(n), cap(n, vector<int>(n, 0)), adj(n) {}

    void addEdge(int u, int v, int w) {
        if (cap[u][v] == 0 && cap[v][u] == 0) {
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        cap[u][v] += w;
    }

    int maxFlow(int s, int t) {
        int flow = 0;
        while (true) {
            vector<int> parent(n, -1);
            parent[s] = s;
            queue<int> q;
            q.push(s);
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                if (u == t) break;
                for (int v : adj[u]) {
                    if (parent[v] == -1 && cap[u][v] > 0) {
                        parent[v] = u;
                        q.push(v);
                    }
                }
            }
            if (parent[t] == -1) break;
            int f = INT_MAX;
            for (int v = t; v != s; v = parent[v])
                f = min(f, cap[parent[v]][v]);
            for (int v = t; v != s; v = parent[v]) {
                cap[parent[v]][v] -= f;
                cap[v][parent[v]] += f;
            }
            flow += f;
        }
        return flow;
    }
};

void bfsFromZ(int sx, int sy) {
    memset(distB, -1, sizeof distB);
    queue<pair<int,int>> q;
    distB[sx][sy] = 0;
    q.push({sx, sy});
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (distB[nx][ny] != -1) continue;
            if (B[nx][ny] == 'Y' || B[nx][ny] == 'Z') continue;
            distB[nx][ny] = distB[x][y] + 1;
            q.push({nx, ny});
        }
    }
}

void buildDP() {
    for (int t = k; t >= 0; --t) {
        for (int x0 = 0; x0 < n; ++x0)
            for (int y0 = 0; y0 < n; ++y0)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y) {
                        int res;
                        if (distB[x0][y0] < t) res = 0;
                        else if (x0 == x && y0 == y) res = 1;
                        else if (t >= k) res = 0;
                        else if (distB[x0][y0] <= t) res = 0;
                        else {
                            res = 0;
                            for (int d = 0; d < 4; ++d) {
                                int nx = x0 + dx[d];
                                int ny = y0 + dy[d];
                                if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
                                if (A[nx][ny] == 'Y' || A[nx][ny] == 'Z') continue;
                                if (reach[t + 1][nx][ny][x][y]) {
                                    res = 1;
                                    break;
                                }
                            }
                        }
                        reach[t][x0][y0][x][y] = res;
                    }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    for (int i = 0; i < n; ++i) cin >> A[i];
    for (int i = 0; i < n; ++i) cin >> B[i];

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (B[i][j] == 'Z') zx = i, zy = j;

    bfsFromZ(zx, zy);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distB[i][j] == -1) distB[i][j] = INF;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = A[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') sourceSet.push_back({i, j});
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = B[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') sinkSet.push_back({i, j});
        }

    buildDP();

    int S = 0;
    int T = (int)sourceSet.size() + (int)sinkSet.size() + 1;
    EdmondsKarp ek(T + 1);

    for (int i = 0; i < (int)sourceSet.size(); ++i)
        ek.addEdge(S, i + 1, A[sourceSet[i].first][sourceSet[i].second] - '0');

    for (int i = 0; i < (int)sinkSet.size(); ++i)
        ek.addEdge((int)sourceSet.size() + i + 1, T,
                   B[sinkSet[i].first][sinkSet[i].second] - '0');

    for (int i = 0; i < (int)sourceSet.size(); ++i)
        for (int j = 0; j < (int)sinkSet.size(); ++j)
            if (reach[0][sourceSet[i].first][sourceSet[i].second]
                     [sinkSet[j].first][sinkSet[j].second])
                ek.addEdge(i + 1, (int)sourceSet.size() + j + 1, INF);

    cout << ek.maxFlow(S, T) << '\n';
    return 0;
}
